def find_insert_position(sorted_values, target):
    """Return the index where target should be inserted to keep the list sorted.

    If target is already present, return the index of its FIRST occurrence.
    """
    low = 0
    high = len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	// Start workers
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	// Feed jobs in a separate goroutine to prevent deadlock
	// when the jobs channel buffer is full (or unbuffered)
	go func() {
		for i := range inputs {
			jobs <- i
		}
		close(jobs)
	}()

	wg.Wait()
	return out
}

package cache

import (
	"container/list"
)

// entry holds the key and value stored in the LRU cache.
type entry struct {
	key   string
	value int
}

// LRU is a fixed-capacity least recently used cache.
type LRU struct {
	capacity int
	cache    map[string]*list.Element
	list     *list.List
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		cache:     make(map[string]*list.Element),
		list:      list.New(),
	}
}

// Get retrieves a value from the cache. If the key exists, it moves the entry to the front.
func (c *LRU) Get(key string) (int, bool) {
	if element, ok := c.cache[key]; ok {
		c.list.MoveToFront(element)
		return element.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache. If the key exists, it updates the value and moves it to the front.
// If the cache is at capacity, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	if element, ok := c.cache[key]; ok {
		c.list.MoveToFront(element)
		element.Value.(*entry).value = value
		return
	}

	if c.list.Len() >= c.capacity {
		c.evict()
	}

	ent := &entry{key: key, value: value}
	element := c.list.PushFront(ent)
	c.cache[key] = element
}

// evict removes the least recently used element from the cache.
func (c *LRU) evict() {
	element := c.list.Back()
	if element != nil {
		c.list.Remove(element)
		kv := element.Value.(*entry)
		delete(c.cache, kv.key)
	}
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return c.list.Len()
}

export function groupConsecutive(values: number[]): number[][] {
  if (values.length === 0) {
    return [];
  }

  const result: number[][] = [];
  let currentRun: number[] = [values[0]];

  for (let i = 1; i < values.length; i++) {
    const prev = values[i - 1];
    const current = values[i];

    if (current === prev + 1) {
      currentRun.push(current);
    } else {
      result.push(currentRun);
      currentRun = [current];
    }
  }

  result.push(currentRun);
  return result;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
// Rewrite this to use async/await and a plain loop. Behaviour must not change,
// including that a cycle throws Error("cycle detected") and that the chain is
// capped at 50 entries with Error("chain too long").
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let currentId: string | null = start;

  while (currentId !== null) {
    if (seen.has(currentId)) {
      throw new Error("cycle detected");
    }
    seen.add(currentId);
    chain.push(currentId);

    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(currentId);
    currentId = node.parent;
  }

  return chain;
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    // BUG: callers report that the running balances are all identical to the
    // final balance, and that AverageDelta is truncated to a whole number.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();

        foreach (var e in entries)
        {
            if (!totals.ContainsKey(e.Account))
            {
                totals[e.Account] = 0;
                running[e.Account] = new List<int>();
            }
            totals[e.Account] += e.Delta;
            running[e.Account].Add(totals[e.Account]);
        }

        var deltas = entries.Select(e => e.Delta).ToList();
        double average = 0;
        if (deltas.Count > 0)
        {
            average = deltas.Average(d => (double)d);
        }

        return (running, totals, average);
    }
}

using UnityEngine;
using System.Collections.Generic;

public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int prewarmCount;

    private Queue<GameObject> pool = new Queue<GameObject>();
    private HashSet<GameObject> activeObjects = new HashSet<GameObject>();

    private void Awake()
    {
        if (prefab == null)
        {
            Debug.LogError("ProjectilePool: Prefab is not assigned.");
            return;
        }

        for (int i = 0; i < prewarmCount; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            pool.Enqueue(obj);
        }
    }

    public GameObject Rent()
    {
        GameObject obj;

        if (pool.Count > 0)
        {
            obj = pool.Dequeue();
        }
        else
        {
            obj = Instantiate(prefab, transform);
        }

        obj.SetActive(true);
        activeObjects.Add(obj);
        return obj;
    }

    public void Return(GameObject go)
    {
        if (go == null) return;

        // Ensure we don't add the same object twice to the pool
        // and only return objects that are actually part of this pool's management
        if (activeObjects.Contains(go))
        {
            activeObjects.Remove(go);
            go.SetActive(false);
            pool.Enqueue(go);
        }
    }

    private void OnDestroy()
    {
        // Cleanup to prevent memory leaks in editor/play mode transitions
        foreach (var obj in pool)
        {
            if (obj != null) Destroy(obj);
        }
        foreach (var obj in activeObjects)
        {
            if (obj != null) Destroy(obj);
        }
    }
}

