using System;

public class TelemetrySender
{
    private readonly NetworkManager _networkManager;

    public TelemetrySender(NetworkManager networkManager)
    {
        _networkManager = networkManager ?? throw new ArgumentNullException(nameof(networkManager));
    }

    public void Send(string opcode, string payload)
    {
        // Opcodes longer than 8 characters must be truncated to their first 8 characters
        // before passing to the NetworkManager.
        string processedOpcode = opcode.Length > 8 ? opcode.Substring(0, 8) : opcode;

        string frame = _networkManager.Encode(processedOpcode, payload);
        _networkManager.Enqueue(frame);
    }
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int count = 0;
        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                count++;
            }
        }
        return count;
    }
}
